={{ 
(() => {
  const date = new Date($('Fetch Latest Appointment For Outbound Dialer').item.json.startTime);

  let hours = date.getHours();
  let minutes = date.getMinutes();

  const ampm = hours >= 12 ? 'PM' : 'AM';

  hours = hours % 12;
  hours = hours ? hours : 12;

  const numberWords = [
    "twelve","one","two","three","four","five","six","seven","eight","nine","ten","eleven"
  ];

  const tensWords = [
    "", "", "twenty", "thirty", "forty", "fifty"
  ];

  const onesWords = [
    "zero","one","two","three","four","five","six","seven","eight","nine"
  ];

  let minuteText = "";

  if (minutes === 0) {
    minuteText = "";
  } else if (minutes < 10) {
    minuteText = " oh " + onesWords[minutes];
  } else if (minutes < 20) {
    const teens = [
      "ten","eleven","twelve","thirteen","fourteen",
      "fifteen","sixteen","seventeen","eighteen","nineteen"
    ];
    minuteText = " " + teens[minutes - 10];
  } else {
    const tens = Math.floor(minutes / 10);
    const ones = minutes % 10;

    minuteText = " " + tensWords[tens];
    if (ones > 0) {
      minuteText += "-" + onesWords[ones];
    }
  }

  return `${numberWords[hours]}${minuteText} ${ampm}`;
})()
}}

={{ 
(() => {
  const appointmentDate = new Date($('Fetch Latest Appointment For Outbound Dialer').item.json.startTime);
  const now = new Date();

  // Normalize both dates (remove time part)
  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  const apptDay = new Date(appointmentDate.getFullYear(), appointmentDate.getMonth(), appointmentDate.getDate());

  const diffTime = apptDay - today;
  const diffDays = Math.round(diffTime / (1000 * 60 * 60 * 24));

  if (diffDays === 0) return "today";
  if (diffDays === 1) return "tomorrow";
  if (diffDays === 2) return "in two days time";

  return `in ${diffDays} days time`;
})()
}}

