parameters.jsCode:
const body = $('Telnyx EOCR Webhook').item.json.body;

let conversationInsights = [];
try {
  conversationInsights = JSON.parse(body.ConversationInsights || '[]');
} catch (e) {
  conversationInsights = [];
}

const CALL_OUTCOME_INSIGHT_ID = 'YOUR_TELNYX_INSIGHT_ID';
const outcomeInsight = conversationInsights.find(i => i.insight_id === CALL_OUTCOME_INSIGHT_ID);

let parsed = {};
if (!outcomeInsight) {
  parsed = {
    call_outcome: 'no_meaningful_conversation',
    call_summary: 'Could not find call outcome insight in webhook payload.',
    user_sentiment: 'unknown',
    call_successful: 'no',
    parse_error: true
  };
} else {
  try {
    parsed = JSON.parse(outcomeInsight.result);
  } catch (e) {
    parsed = {
      call_outcome: 'no_meaningful_conversation',
      call_summary: outcomeInsight.result || 'Could not parse insight result',
      user_sentiment: 'unknown',
      call_successful: 'no',
      parse_error: true
    };
  }
}

let recordingUrl = null;
let callDurationSecs = null;
try {
  const recordings = JSON.parse(body.Recordings || '[]');
  const dual = recordings.find(r => r.channels === 'dual') || recordings[0];
  if (dual) {
    recordingUrl = dual.download_urls?.mp3 || null;
    if (dual.start_time && dual.end_time) {
      const startMs = new Date(dual.start_time).getTime();
      const endMs = new Date(dual.end_time).getTime();
      callDurationSecs = Math.round((endMs - startMs) / 1000);
    }
  }
} catch (e) {
  recordingUrl = null;
  callDurationSecs = null;
}

return [{
  json: {
    ...parsed,
    recording_url: recordingUrl,
    call_duration_secs: callDurationSecs
  }
}];

