const contact = $('Search GHL — DV Inbound').item.json.contacts?.[0];
const events = $input.first().json.events || [];
const customFields = contact?.customFields || [];

function getField(fieldId) {
  const field = customFields.find(f => f.id === fieldId);
  return field ? field.value : null;
}

const FIELD_IDS = {
  service_type: "YOUR_GHL_FIELD_ID_SERVICE_TYPE"
};

let appointmentTime = "your scheduled time";
let day = "your appointment day";
let serviceType = getField(FIELD_IDS.service_type) || "your plumbing service";

if (events.length > 0) {
  const valid = events.filter(e => e.appointmentStatus === "confirmed" && !e.deleted);

  if (valid.length > 0) {
    valid.sort((a, b) => new Date(b.dateAdded) - new Date(a.dateAdded));
    const latest = valid[0];

    const date = new Date(latest.startTime);
    let hours = date.getHours();
    let minutes = date.getMinutes();
    const ampm = hours >= 12 ? 'PM' : 'AM';
    hours = hours % 12 || 12;

    const numberWords = ["twelve","one","two","three","four","five","six","seven","eight","nine","ten","eleven"];
    const tensWords = ["","","twenty","thirty","forty","fifty"];
    const onesWords = ["zero","one","two","three","four","five","six","seven","eight","nine"];
    const teens = ["ten","eleven","twelve","thirteen","fourteen","fifteen","sixteen","seventeen","eighteen","nineteen"];

    let minuteText = "";
    if (minutes === 0) {
      minuteText = "";
    } else if (minutes < 10) {
      minuteText = " oh " + onesWords[minutes];
    } else if (minutes < 20) {
      minuteText = " " + teens[minutes - 10];
    } else {
      const tens = Math.floor(minutes / 10);
      const ones = minutes % 10;
      minuteText = " " + tensWords[tens];
      if (ones > 0) minuteText += "-" + onesWords[ones];
    }

    appointmentTime = `${numberWords[hours]}${minuteText} ${ampm}`;

    const appointmentDate = new Date(latest.startTime);
    const now = new Date();
    const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    const apptDay = new Date(appointmentDate.getFullYear(), appointmentDate.getMonth(), appointmentDate.getDate());
    const diffDays = Math.round((apptDay - today) / (1000 * 60 * 60 * 24));

    if (diffDays === 0) day = "today";
    else if (diffDays === 1) day = "tomorrow";
    else if (diffDays === 2) day = "in two days time";
    else day = `in ${diffDays} days time`;
  }
}

return [{
  json: {
    dynamic_variables: {
      first_name: contact?.firstName || "there",
      last_name: contact?.lastName || "",
      user_number: contact?.phone || "",
      service_type: serviceType,
      appointment_time: appointmentTime,
      day: day
    }
  }
}];

