const first_name = ($json.first_name || "").trim();
const last_name = ($json.last_name || "").trim();
const phone_number = ($json.phone_number || "").trim();
const absolute_time = ($json.absolute_time || "").trim();

const errors = [];

function validateName(name, label, required) {
  if (!name) {
    if (required) errors.push(`${label} is missing.`);
    return;
  }
  const lower = name.toLowerCase();
  if (["null", "undefined", "n/a", "none"].includes(lower)) {
    if (required) errors.push(`${label} is a literal "${name}" placeholder, not a real name.`);
    return;
  }
  if (name.length > 50) {
    errors.push(`${label} is implausibly long (${name.length} chars).`);
  }
  if (/\d/.test(name)) {
    errors.push(`${label} contains digits, not a plausible name.`);
  }
  if (/[.!?]{1,}\s+\w+\s+\w+/.test(name) || name.split(/\s+/).length > 4) {
    errors.push(`${label} looks sentence-shaped, not a plausible name.`);
  }
}

validateName(first_name, "first_name", true);
validateName(last_name, "last_name", false);

if (!phone_number) {
  errors.push("phone_number is missing.");
} else {
  const digitsOnly = phone_number.replace(/\D/g, "");
  if (digitsOnly.length < 10 || digitsOnly.length > 11) {
    errors.push(`phone_number "${phone_number}" does not look like a valid NANP phone number.`);
  }
}

if (!absolute_time) {
  errors.push("absolute_time is missing.");
} else {
  const parsed = new Date(absolute_time);
  if (isNaN(parsed.getTime())) {
    errors.push(`absolute_time "${absolute_time}" is not a parseable date.`);
  } else {
    const now = new Date();
    const fiveMinAgo = new Date(now.getTime() - 5 * 60 * 1000);
    const thirtyDaysOut = new Date(now.getTime() + 30 * 24 * 60 * 60 * 1000);
    if (parsed < fiveMinAgo) {
      errors.push(`absolute_time "${absolute_time}" is in the past.`);
    }
    if (parsed > thirtyDaysOut) {
      errors.push(`absolute_time "${absolute_time}" is more than 30 days out.`);
    }
  }
}

return {
  json: {
    ...$json,
    validation_errors: errors,
    is_valid: errors.length === 0,
  }
};

const first_name = ($json.first_name || "").trim();
const last_name = ($json.last_name || "").trim();
const phone_number = ($json.phone_number || "").trim();

const errors = [];

function validateName(name, label, required) {
  if (!name) {
    if (required) errors.push(`${label} is missing.`);
    return;
  }
  const lower = name.toLowerCase();
  if (["null", "undefined", "n/a", "none"].includes(lower)) {
    if (required) errors.push(`${label} is a literal "${name}" placeholder, not a real name.`);
    return;
  }
  if (name.length > 50) {
    errors.push(`${label} is implausibly long (${name.length} chars).`);
  }
  if (/\d/.test(name)) {
    errors.push(`${label} contains digits, not a plausible name.`);
  }
  if (/[.!?]{1,}\s+\w+\s+\w+/.test(name) || name.split(/\s+/).length > 4) {
    errors.push(`${label} looks sentence-shaped, not a plausible name.`);
  }
}

validateName(first_name, "first_name", true);
validateName(last_name, "last_name", false);

if (!phone_number) {
  errors.push("phone_number is missing.");
} else {
  const digitsOnly = phone_number.replace(/\D/g, "");
  if (digitsOnly.length < 10 || digitsOnly.length > 11) {
    errors.push(`phone_number "${phone_number}" does not look like a valid NANP phone number.`);
  }
}

return {
  json: {
    ...$json,
    validation_errors: errors,
    is_valid: errors.length === 0,
  }
};

