const summary = ($json.call_summary || "").toLowerCase();

// Telnyx's AI insight writes call_summary freely from the real transcript - when Mia
// initially heard "cancel" but the customer actually said "confirm" (or a similar
// mishearing that got corrected mid-call), the model tends to describe it using
// language like this. Not a fixed field Telnyx sets - inferred from free text,
// so this is a heuristic, not a guarantee. Cancelled is the single highest-cost
// wrong classification for an appointment-reminder agent (a wanted appointment
// gets silently dropped), so it gets the same extra scrutiny SunPath gives
// not_qualified misclassifications.
const mishearingSignals = [
  "mishear",
  "misheard",
  "mis-hear",
  "corrected",
  "correction",
  "initially thought",
  "initially heard",
  "originally thought",
  "originally heard",
  "walked back",
  "mix-up",
  "mix up",
  "misunderstood",
  "clarified",
];

const followedMishearing = mishearingSignals.some((s) => summary.includes(s));

return [
  {
    json: {
      ...$json,
      needs_human_followup: followedMishearing ? "true" : "false",
    },
  },
];

